.sl-faq-tabbed { background-color: var(--smartlearn-bg); padding-block: clamp(3rem, 6vw, 5rem); padding-inline: clamp(1rem, 4vw, 2rem); width: 100%; font-family: var(--smartlearn-body-font, system-ui, sans-serif); }
.sl-faq-tabbed .sl-container { max-width: 800px; margin-inline: auto; }
.sl-faq-tabbed .sl-header { text-align: center; margin-bottom: 2rem; }
.sl-faq-tabbed .sl-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.85rem, 3.5vw, 2.5rem); font-weight: 800; color: var(--smartlearn-text); margin: 0; }
.sl-faq-tabbed .sl-tabs { display: flex; justify-content: center; gap: 0.75rem; margin-bottom: 2.5rem; flex-wrap: wrap; }
.sl-faq-tabbed .sl-tab { min-height: 44px; background: transparent; border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.35)); color: var(--smartlearn-text-muted); padding: 0.5rem 1.5rem; border-radius: 999px; font-weight: 600; cursor: pointer; transition: background-color 0.25s ease, color 0.25s ease, border-color 0.25s ease; }
.sl-faq-tabbed .sl-tab:hover { border-color: var(--smartlearn-primary); color: var(--smartlearn-text); }
.sl-faq-tabbed .sl-tab:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-faq-tabbed .sl-tab.active { background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); border-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); }
.sl-faq-tabbed .sl-tab-content { display: flex; flex-direction: column; gap: 1.5rem; }
.sl-faq-tabbed[data-sl-init="1"] .sl-tab-content { display: none; animation: sl-faq-tabbed-fade 0.25s ease; }
.sl-faq-tabbed[data-sl-init="1"] .sl-tab-content.active { display: flex; }
.sl-faq-tabbed:not([data-sl-init="1"]) .sl-tab-content { margin-bottom: 1.5rem; }
@keyframes sl-faq-tabbed-fade { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.sl-faq-tabbed .sl-card { background: var(--smartlearn-card-bg, transparent); border: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); border-radius: var(--smartlearn-radius, 8px); padding: clamp(1.5rem, 3vw, 2rem); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); }
.sl-faq-tabbed .sl-q { font-family: var(--smartlearn-heading-font, inherit); font-size: 1.25rem; font-weight: 700; color: var(--smartlearn-text); margin-bottom: 0.75rem; }
.sl-faq-tabbed .sl-a { font-size: 1rem; color: var(--smartlearn-text-muted); line-height: 1.6; margin: 0; }
@media (prefers-reduced-motion: reduce) { .sl-faq-tabbed .sl-tab { transition: none; } .sl-faq-tabbed[data-sl-init="1"] .sl-tab-content { animation: none; } }

