(function() {
  var init = function() {
    document.querySelectorAll('.sl-faq-tabbed').forEach(function(section, sIdx) {
      if (section.dataset.slInit === '1') return;
      section.dataset.slInit = '1';
      var uid = 'sl-faq-tab-' + sIdx + '-' + Math.random().toString(36).slice(2, 7);
      var tabs = Array.prototype.slice.call(section.querySelectorAll('.sl-tab'));
      var panels = Array.prototype.slice.call(section.querySelectorAll('.sl-tab-content'));
      tabs.forEach(function(tab, tIdx) {
        var key = tab.getAttribute('data-target');
        var panel = panels.find(function(p) { return p.getAttribute('data-sl-panel') === key; });
        var tabId = uid + '-tab-' + tIdx;
        tab.id = tabId;
        if (panel) {
          var panelId = uid + '-panel-' + tIdx;
          panel.id = panelId;
          tab.setAttribute('aria-controls', panelId);
          panel.setAttribute('aria-labelledby', tabId);
        }
      });
      var activate = function(tab, focusTab) {
        var targetKey = tab.getAttribute('data-target');
        tabs.forEach(function(t) {
          var isSel = t === tab;
          t.classList.toggle('active', isSel);
          t.setAttribute('aria-selected', isSel ? 'true' : 'false');
          t.tabIndex = isSel ? 0 : -1;
        });
        panels.forEach(function(p) { p.classList.remove('active'); p.hidden = true; });
        var activePanel = panels.find(function(p) { return p.getAttribute('data-sl-panel') === targetKey; });
        if (activePanel) { activePanel.classList.add('active'); activePanel.hidden = false; }
        if (focusTab) tab.focus();
      };
      var initialTab = tabs.find(function(t) { return t.classList.contains('active'); }) || tabs[0];
      if (initialTab) activate(initialTab, false);
      tabs.forEach(function(tab, idx) {
        tab.addEventListener('click', function() { activate(tab, false); });
        tab.addEventListener('keydown', function(e) {
          var isRtl = getComputedStyle(section).direction === 'rtl';
          var nextIdx = idx;
          if (e.key === 'ArrowRight') nextIdx = isRtl ? (idx - 1 + tabs.length) % tabs.length : (idx + 1) % tabs.length;
          else if (e.key === 'ArrowLeft') nextIdx = isRtl ? (idx + 1) % tabs.length : (idx - 1 + tabs.length) % tabs.length;
          else if (e.key === 'Home') nextIdx = 0;
          else if (e.key === 'End') nextIdx = tabs.length - 1;
          else return;
          e.preventDefault();
          activate(tabs[nextIdx], true);
        });
      });
    });
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
